// Auto-generated by r2factor. Manual edits will be overwritten on next split.

use crate::types::{Axis, ContainerNode, SlotNode};

pub(super) fn resolve_axis(container: &ContainerNode<'_>, width: f32, height: f32) -> Axis {
    match container.auto_axis {
        Some(threshold) => {
            if height > 0.0 && (width / height) > threshold {
                Axis::Horizontal
            } else {
                Axis::Vertical
            }
        }
        None => container.axis,
    }
}

pub(super) fn resolve_display_tier(slot: &SlotNode<'_>, main_size: f32) -> Option<String> {
    if slot.display_tiers.is_empty() {
        return None;
    }

    // Find the tier with the largest min_size that still fits
    let mut best: Option<&str> = None;
    let mut best_threshold = f32::NEG_INFINITY;

    for tier in slot.display_tiers {
        if main_size >= tier.min_size && tier.min_size > best_threshold {
            best = Some(tier.name);
            best_threshold = tier.min_size;
        }
    }

    best.map(String::from)
}
